@IsTest
private class OwnedJsonDateObservation {
    public class Window {
        public Date starts { get; }
        public Date ends { get; }
    }
    public class Envelope {
        public Map<String,List<Window>> entries { get; }
    }
    private static Object parts(Date value) {
        if(value==null) return null;
        return new List<Object>{value.year(),value.month(),value.day(),JSON.serialize(value)};
    }
    private static Object scalar(String value) {
        try { return parts((Date)JSON.deserialize(JSON.serialize(value),Date.class)); }
        catch(Exception e) { return new List<Object>{e.getTypeName(),e.getMessage()}; }
    }
    private static Object nested(String first,String last) {
        String body='{"entries":{"owned":[{"starts":'+JSON.serialize(first)+',"ends":'+JSON.serialize(last)+'}]}}';
        try {
            Envelope value=(Envelope)JSON.deserialize(body,Envelope.class);
            Window row=value.entries.get('owned')[0];
            return new List<Object>{parts(row.starts),parts(row.ends)};
        } catch(Exception e) { return new List<Object>{e.getTypeName(),e.getMessage()}; }
    }
    private static void observe(String label,String first,String last) {
        Map<String,Object> result=new Map<String,Object>{
            'label'=>label,'scalarFirst'=>scalar(first),'scalarLast'=>scalar(last),'nested'=>nested(first,last)
        };
        System.assert(false,'OWNED_JSON_DATE_OBSERVATION|'+JSON.serialize(result));
    }
    @IsTest static void shortYears() { observe('short','1-12-25','33-04-18'); }
    @IsTest static void paddedYears() { observe('padded','0001-12-25','0033-04-18'); }
    @IsTest static void ordinaryISO() { observe('iso','2004-02-29','2025-12-01'); }
    @IsTest static void invalidAndNull() { observe('controls','2004-02-30',null); }
}

