@IsTest private class OwnedJsonDateEqualityObservation {
 public class Window { public Date starts {get;} public Date ends {get;} }
 public class Envelope { public Map<String,List<Window>> entries {get;} }
 private static Envelope decode(String first,String last) {
  String body='{"entries":{"owned":[{"starts":'+JSON.serialize(first)+',"ends":'+JSON.serialize(last)+'}]}}';
  return (Envelope)JSON.deserialize(body,Envelope.class);
 }
 @IsTest static void shortAndPaddedEquality() {
  Map<String,Object> result=new Map<String,Object>();
  try {
   Date one=(Date)JSON.deserialize('"1-12-25"',Date.class);
   Date paddedOne=(Date)JSON.deserialize('"0001-12-25"',Date.class);
   Date thirtyThree=(Date)JSON.deserialize('"33-04-18"',Date.class);
   Date paddedThirtyThree=(Date)JSON.deserialize('"0033-04-18"',Date.class);
   Window a=decode('1-12-25','33-04-18').entries.get('owned')[0];
   Window b=decode('0001-12-25','0033-04-18').entries.get('owned')[0];
   result.put('scalarEqual',new List<Boolean>{one==paddedOne,thirtyThree==paddedThirtyThree});
   result.put('nestedEqual',new List<Boolean>{a.starts==b.starts,a.ends==b.ends});
   result.put('scalarSerialized',new List<String>{JSON.serialize(one),JSON.serialize(thirtyThree)});
   result.put('nestedSerialized',new List<String>{JSON.serialize(a.starts),JSON.serialize(a.ends)});
  } catch(Exception e) {result.put('exception',new List<Object>{e.getTypeName(),e.getMessage()});}
  System.assert(false,'OWNED_JSON_DATE_EQUALITY|'+JSON.serialize(result));
 }
}

